() => {
  const classIds = [
    'd042bdde-581d-56bf-91e1-7f803af4d78f', // Aug 31
    'da07eb68-a9c6-5e86-a450-75c2cb870f67', // Sep 7
    'e8f515cf-4bbf-5ce6-9cb5-9908fcad5402', // Sep 14
    '98423d3b-8eb7-5fbb-8cec-0ba2e8debcb3', // Sep 21
    'b5513980-2e87-55d4-b499-f44754555350', // Sep 28
    '323b4b89-3073-54c1-92b8-8ef207a5385b', // Oct 5
  ];

  const bookClass = (id) => fetch('/graphql', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
